-- Disposable fixtures inside a transaction. No emails, real staff or payments.
begin;
create temp table work_test_ids(owner_id uuid, editor_id uuid, session_id uuid, editor_session uuid, factor_id uuid, editor_factor uuid);
insert into work_test_ids values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant select on work_test_ids to authenticated,anon;
insert into auth.users(id,email,email_confirmed_at) select owner_id,'owner-fixture@example.invalid',now() from work_test_ids union all select editor_id,'editor-fixture@example.invalid',now() from work_test_ids;
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) select factor_id,owner_id,'totp'::auth.factor_type,'verified'::auth.factor_status,'TEST-NOT-A-REAL-AUTHENTICATOR',now(),now() from work_test_ids union all select editor_factor,editor_id,'totp'::auth.factor_type,'verified'::auth.factor_status,'TEST-NOT-A-REAL-AUTHENTICATOR',now(),now() from work_test_ids;
insert into auth.sessions(id,user_id,factor_id,aal,created_at,updated_at) select session_id,owner_id,factor_id,'aal2'::auth.aal_level,now(),now() from work_test_ids union all select editor_session,editor_id,editor_factor,'aal2'::auth.aal_level,now(),now() from work_test_ids;
insert into public.work_members(email,user_id,role) select 'owner-fixture@example.invalid',owner_id,'owner' from work_test_ids union all select 'editor-fixture@example.invalid',editor_id,'editor' from work_test_ids;
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'aal','aal1','session_id',session_id)::text,true) from work_test_ids;
set local role authenticated;
do $$begin
 if public.work_has_access('finance') then raise exception 'AAL1 was allowed'; end if;
 if (select count(*) from public.work_documents)<>0 then raise exception 'AAL1 financial data leak'; end if;
 if (select count(*) from public.work_settings)<>0 then raise exception 'AAL1 settings leak'; end if;
end;$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'aal','aal2','session_id',session_id)::text,true) from work_test_ids;
set local role authenticated;
do $$
declare payload jsonb; quote_id uuid; quote_number text; receipt_id uuid; refused boolean; amount bigint; new_revision uuid; staff_id uuid; evidence uuid=gen_random_uuid(); owner_uid uuid=auth.uid();
begin
 if not public.work_has_access('finance') then raise exception 'Owner AAL2 denied'; end if;
 payload='{"kind":"quotation","customer":{"name":"Fixture Customer","email":"","phone":"","address":""},"date":"2026-10-22","valid_until":"","currency":"NGN","items":[{"description":"TEST ONLY","quantity":3,"unit_minor":10001}],"discount_minor":3,"tax_bps":750,"notes":"","payment_method":"","payment_reference":"","payment_confirmed":false,"source_id":""}'::jsonb;
 insert into public.work_documents(kind,payload,total_minor) values('quotation',payload,1) returning id,total_minor into quote_id,amount;
 if amount<>32250 then raise exception 'Database calculation failed: %',amount; end if;
 update public.work_documents set status='issued' where id=quote_id returning number into quote_number;
 if quote_number !~ '^LUT-QUO-[0-9]{4}-[0-9]{6,}$' then raise exception 'Number format failed'; end if;
 refused=false;begin update public.work_documents set id=gen_random_uuid() where id=quote_id;exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Record ID was editable';end if;
 if not exists(select 1 from public.work_documents d where d.id=quote_id and d.payload ? 'company') then raise exception 'Company snapshot missing'; end if;
 refused=false;begin update public.work_documents d set payload=jsonb_set(d.payload,'{notes}','"Edited"') where id=quote_id;exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Issued record was editable';end if;
 refused=false;begin delete from public.work_documents where id=quote_id;exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Issued record was deletable';end if;
 perform public.work_business(jsonb_build_object('command','misc','action','file','id',evidence,'area','finance','name','Fixture evidence','path',owner_uid::text||'/'||evidence||'.jpg','size',10,'sha256',repeat('a',64)));
 insert into storage.objects(bucket_id,name) values('work-evidence',owner_uid::text||'/'||evidence||'.jpg');
 payload=payload||jsonb_build_object('evidence_id',evidence,'kind','receipt','items',jsonb_build_array(jsonb_build_object('description','Fixture receipt','quantity',1,'unit_minor',10000)),'discount_minor',0,'tax_bps',0,'source_id',quote_id,'payment_method','Test fixture','payment_confirmed',true);
 insert into public.work_documents(kind,payload) values('receipt',payload) returning id into receipt_id;
 update public.work_documents set status='issued' where id=receipt_id;
 refused=false;begin update public.work_documents d set status='void',payload=d.payload||'{"void_reason":"Fixture cancellation"}'::jsonb where id=quote_id;exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Source with issued receipt was voided';end if;
 payload=jsonb_set(payload,'{items,0,unit_minor}','30000');
 insert into public.work_documents(kind,payload) values('receipt',payload) returning id into receipt_id;
 refused=false;begin update public.work_documents set status='issued' where id=receipt_id;exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Overpayment receipt was issued';end if;
 refused=false;begin insert into public.work_documents(kind,payload) values('quotation','{"kind":"quotation"}');exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Malformed payload accepted';end if;
 refused=false;begin update public.work_audit set action='erased';exception when insufficient_privilege then refused=true;end;
 if not refused then raise exception 'Audit could be changed';end if;
 new_revision=public.work_publish_site((select version from public.work_site_drafts where id=1));
 if not exists(select 1 from public.work_public_site where work_public_site.revision=new_revision) then raise exception 'Publication failed';end if;
 if not public.work_backup_snapshot() ? 'counters' then raise exception 'Backup missing numbering counters';end if;
 insert into public.work_staff(payload) values('{"name":"Fixture Staff","title":"TEST ONLY","staff_number":"FIXTURE-001","department":"","email":"","phone":"","issued_on":"2026-10-22","expires_on":"","active":true,"photo_path":""}') returning id into staff_id;
 refused=false;begin update public.work_staff set id=gen_random_uuid() where id=staff_id;exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Staff ID was editable';end if;
 insert into storage.objects(bucket_id,name) values('work-staff','FIXTURE-NO-FILE.jpg');
 if (select count(*) from storage.objects where name='FIXTURE-NO-FILE.jpg')<>1 then raise exception 'Owner photo access denied';end if;
end;$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',editor_id,'aal','aal2','session_id',editor_session)::text,true) from work_test_ids;
set local role authenticated;
do $$declare refused boolean;begin
 if not public.work_has_access('session') or not public.work_has_access('content') then raise exception 'Editor content access denied';end if;
 if public.work_has_access('finance') or public.work_has_access('members') then raise exception 'Editor role escalation';end if;
 if (select count(*) from public.work_documents)<>0 then raise exception 'Editor financial data leak';end if;
 if (select count(*) from public.work_staff)<>0 or (select count(*) from storage.objects)<>0 then raise exception 'Editor staff data leak';end if;
 if (select count(*) from public.work_site_drafts)<>1 then raise exception 'Editor draft read failed';end if;
 refused=false;begin perform public.work_set_member('escalate@example.invalid','owner',true);exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Editor could grant owner';end if;
 refused=false;begin perform public.work_backup_snapshot();exception when raise_exception then refused=true;end;
 if not refused then raise exception 'Editor could export backups';end if;
end;$$;
reset role;
update public.work_members set active=false where email='owner-fixture@example.invalid';
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'aal','aal2','session_id',session_id)::text,true) from work_test_ids;
set local role authenticated;
do $$begin if public.work_has_access('finance') then raise exception 'Disabled member retained access';end if;end;$$;
reset role;
update public.work_members set active=true where email='owner-fixture@example.invalid';
update auth.users set email='changed-fixture@example.invalid' where id=(select owner_id from work_test_ids);
set local role authenticated;
do $$begin if public.work_has_access('finance') then raise exception 'Unapproved changed email retained access';end if;end;$$;
reset role;
update auth.users set email='owner-fixture@example.invalid' where id=(select owner_id from work_test_ids);
update auth.mfa_factors set status='unverified' where id=(select factor_id from work_test_ids);
set local role authenticated;
do $$begin if public.work_has_access('finance') then raise exception 'Unverified factor retained access';end if;end;$$;
reset role;
update auth.mfa_factors set status='verified' where id=(select factor_id from work_test_ids);
update auth.sessions set created_at=now()-interval '13 hours' where id=(select session_id from work_test_ids);
set local role authenticated;
do $$begin if public.work_has_access('finance') then raise exception 'Expired session retained access';end if;end;$$;
reset role;
set local role anon;
do $$declare refused boolean;begin
 if (select count(*) from public.work_public_site)<>1 then raise exception 'Public snapshot unavailable';end if;
 refused=false;begin perform * from public.work_staff;exception when insufficient_privilege then refused=true;end;
 if not refused then raise exception 'Anonymous staff access';end if;
 refused=false;begin perform public.work_backup_snapshot();exception when insufficient_privilege then refused=true;end;
 if not refused then raise exception 'Anonymous backup access';end if;
end;$$;
reset role;
select 'PASS: AAL1, owner/editor separation, numbering, totals, snapshots, issued lock, overpayment, void ordering, audit immutability, public snapshot, revoked/expired sessions, anonymous denials. Fixtures rolled back.' result;
rollback;
